# -*- coding: utf-8 -*-
import json, re

d=json.load(open('article_data.json',encoding='utf-8'))

def setp(si,pi,txt):
    d['sections'][si]['paras'][pi]=txt

# ---- S1 2 背景与动机 ----
setp(1,1,"考虑一个源模型和一个目标模型，层数分别为 L_s 与 L_t，均使用分组查询注意力（GQA）。两者的 KV 头数与每头维度可以不同：分别记为 n_kv 与 d_h（上标 s 表示源、t 表示目标）。对长度 T 的输入序列，源模型每一层、每一个头都会产生对应的键（Key）与值（Value）；用 C_S 表示源模型全部层与头的完整 KV 缓存，C_T 表示目标模型的完整 KV 缓存。源与目标同属一个模型家族、共享分词器，因此同一段输入对两者长度都是 T。当两边 KV 头数与每头维度一致（n_kv^s=n_kv^t 且 d_h^s=d_h^t）时，就构成一对 matched-KV（匹配 KV）模型——即使层数 L_s、L_t 或参数量相差很大，这一条件也不受影响。")
setp(1,2,"我们想找到一个映射 f，把源的完整缓存 C_S 变换为 C_hat_T，让目标模型用 C_hat_T 代替自己的缓存解码时，输出与使用原始目标缓存基本等价。")
setp(1,3,"对具有度量 m 的下游任务 τ，我们用目标模型的下游准确率（而非重建误差）来衡量迁移质量。映射 f 被拆成逐头的键映射 f_K 与值映射 f_V，为目标模型的每一层、每一个头分别生成键和值。")
setp(1,7,"在确定映射器架构之前，先要弄清跨模型 KV 之间到底有没有可用的线性结构。以 Qwen3 为例（结论可推广到其他 matched-KV 对），我们探测三类缓存：K_rope 是模型实际使用的键；K_stripped 是用 R_Θ 的逆变换剥掉位置相关 RoPE 旋转后的键；V 是值，本身不携带位置编码。对每一类缓存、每一个（源层、目标层、头）三元组，我们在 token 级别做单源普通最小二乘回归：从 FineWeb-Edu 序列二次采样 N 个校准 token，用源模型逐 token 的键/值特征向量去预测目标模型的对应特征。")
setp(1,8,"这里的拟合只是探测（单一源层），不是最终的生产映射器——后者会拼接多个源层并加岭正则化。我们用决定系数 R² 衡量拟合质量，再对全部目标头取平均，得到每个（源层、目标层）组合的头平均 R²；画成热力图（行是源层、列是目标层，见图 2）后，可以看出四种定性模式。逐对的定量数值另有报告。")
setp(1,9,"(1) 高线性拟合：在最可预测的目标层上，单一线性回归已能解释跨模型 KV 方差的很大一部分。沿对角线方向头平均 R² 远高于零；在热力图峰值处，Qwen3 14B→32B 的最优单一源-目标对在 K_stripped 上达到 R²=0.81，较弱的 8B→32B 也有 0.65。(2) 模型越接近，对角线越清晰：架构与深度差距越大，模式越弥散。(3) RoPE 会污染拟合：去掉 RoPE 通常让对角线更清晰，这促成了位置-内容分解。(4) K 比 V 更可预测：两者的头平均 R² 通常相差约 0.2。")
setp(1,10,"上面的探针只用单一源层；我们用贪心前向选择做扩展——迭代加入让 R² 增幅最大的源层，因为互补信息分散在多个源层里。在 Qwen3 14B→32B 上，对 K_stripped，k=1 只达到 k=all 时 R² 的 66%，对 V 只有 42%；收益最大的阶段是 k=1 到 k=4，到 k=6 时 R² 已接近 k=all 的水平。这为 top-k 源层选择提供了依据。")

# ---- S2 3 映射器设计 ----
setp(2,2,"源与目标在层数（L_s≠L_t）、头维度（d_h^s≠d_h^t）乃至 KV 头数量（n_kv^s≠n_kv^t）上都可能存在差异。我们为每个目标（层、头）对单独拟合一个线性映射来吸收这些差异：")
setp(2,3,"把 k 个选定源层的 Key 特征拼成矩阵 X_K，乘上该（层、头）专用的岭回归权重 W_K，得到目标的键估计；Value 侧同理，用独立的 W_V 拟合。整套映射按目标层与目标头逐个独立求解，每个都是闭式线性问题。")
setp(2,4,"把 N 个校准 token 堆叠起来，得到设计矩阵 X 与响应矩阵 Y。我们用岭回归（ridge）而非纯最小二乘，取 λ=0.01 来保证数值稳定：k 较大时特征维度可达数万，且选出的 top-k 个源层高度相关，使 X⊤X 接近奇异；Tikhonov 正则项让求逆稳定，引入的偏差可以忽略。这个线性问题存在闭式解。")
setp(2,5,"求解前先对 X 与 Y 做中心化，因此闭式解给出的是斜率，偏置项再通过均值恢复（b=Ȳ−X̄W）。校准数据由 500 条长度 1024 的 FineWeb-Edu 序列、以 stride-4 子采样构成，每个目标头约对应 N≈128K 个校准 token。映射器总大小（K 与 V 合计）随目标头数、选定源层数与特征维度线性增长（逐对规模见附录 D）。在单台 8×H100 节点上，拟合一对约需 47–87 分钟，全程无需基于梯度的训练；拟合时间随目标头数近似次线性增长，因为最耗时的 X⊤X 构造每个目标层只算一次、并在该层所有头之间共享（逐对时间见附录 E）。")
setp(2,7,"源与目标层数不同，因此要决定每个目标层该从哪些源层取信息。2.3 节表明，对给定的目标层，并非所有源层都同样有信息量。于是针对每个目标层 l，我们按去除 RoPE 后的键和值的头平均 R² 选出前 k 个源层，拼接它们的 KV 特征，再套用 3.1 节的多源岭回归。")
setp(2,8,"其中 K̄ 是某个选定源层全部 Key 头的拼接，选出的源层集合记为 {l_1,…,l_k}；Value 侧用同样方式构造 X_V。目标层内的所有头共享同一组选定源层，从而允许信息跨头流动。源层数量 k 是一个超参数，逐对通过扫描确定；跨层源选择是映射器的三个组件之一。")
setp(2,10,"标准 RoPE（Su et al., 2024）对查询和键施加与位置相关的旋转，KV 缓存只保存旋转后的键（k_RoPE(t)=R_Θ(t)·k_content），查询则在解码时重新计算。把位置与内容解耦让映射管线变得模块化：每个头的岭回归权重都在无位置空间里拟合，因此既能跨不同 RoPE 配置的模型对复用，也能在目标 RoPE 支持的任意位置上生效。若直接把映射器拟合到带 RoPE 的键上，短上下文基准也能在噪声范围内工作，但权重会被绑定到拟合时见过的 1024 token 位置分布上；解耦形式则在构造上就能外推到更长上下文，这对动辄服务 32k token 提示的生产场景很关键。")
setp(2,11,"具体做法是：先剥离源的 RoPE，在无位置空间里用 W_K 做线性变换，再按目标位置重新编码，即 K_hat_t = (K_s·R_Θ_s⁻¹(t)·W_K + b_K)·R_Θ_t(t)。校准阶段，回归目标 Y 由目标真值键去掉自身 RoPE 后构建，因此 W_K 完全在无位置空间中拟合；由于 R_Θ 是正交矩阵，求逆在可忽略的开销内精确。Value 不携带位置编码，直接映射即可。")

json.dump(d, open('article_data.json','w',encoding='utf-8'), ensure_ascii=False, indent=2)
blob=json.dumps(d,ensure_ascii=False)
print('rewritten. residuals:')
print(' backslash-cmd:', re.findall(r'\\[a-zA-Z]+', blob)[:8])
print(' {=}:', blob.count('{=}'), '  \\, :', blob.count('\\,'), '  ^{:', blob.count('^{'), '  _{:', blob.count('_{'))
